import math

def kl_penalty(logp_theta: float, logp_ref: float) -> float:
    """Unbiased per-token KL estimate between the policy and a frozen reference."""
    ratio = math.exp(logp_ref - logp_theta)
    return round(ratio - math.log(ratio) - 1, 4)

print(kl_penalty(-2.1, -2.4))

import math

def kl_penalty(logp_theta: float, logp_ref: float) -> float:
    ratio = math.exp(logp_ref - logp_theta)
    return round(ratio - math.log(ratio) - 1, 4)

def grpo_objective(surrogate: float, kl: float, beta: float = 0.04) -> float:
    """GRPO's final objective: clipped surrogate minus a weighted KL penalty."""
    return round(surrogate - beta * kl, 4)

print(grpo_objective(0.1494, 0.0408))
